<?php
$root=dirname(__DIR__);require_once $root.'/app/bootstrap.php';require_once $root.'/app/MigrationService.php';MigrationService::run();require_once $root.'/app/AuthService.php';require_once $root.'/app/UserProfileService.php';AuthService::boot();$user=AuthService::requireLogin();$error=null;$notice=null;$generatedUrl=null;
try{if(!empty($_GET['verify_email'])){UserProfileService::confirmEmailChange((int)$user['user_id'],(string)$_GET['verify_email']);$notice='Your new email address is verified and active.';$user=AuthService::currentUser()??$user;}}
catch(Throwable $e){$error=$e->getMessage();}
if($_SERVER['REQUEST_METHOD']==='POST'){try{AuthService::requireCsrf();$action=(string)($_POST['action']??'');
 if($action==='upload_profile_photo'){UserProfileService::uploadPhoto($user,$_FILES['profile_photo']??[]);$notice='Profile photo updated.';}
 if($action==='request_email_change'){$result=UserProfileService::requestEmailChange($user,(string)($_POST['new_email']??''));$notice=$result['sent']?'Verification sent to your new email address.':'Email delivery was unavailable. Use the verification link below.';$generatedUrl=$result['url'];}
 if($action==='invite_player'){$result=AuthService::createInvitation((string)($_POST['email']??''),(int)$user['user_id']);$notice=$result['sent']?'Player invitation sent.':'Email delivery was unavailable. Share the invitation link below.';$generatedUrl=$result['url'];}
 if($action==='request_friend'){UserProfileService::requestFriend((int)$user['user_id'],(string)($_POST['email']??''));$notice='Friend request sent.';}
 if($action==='friend_accept'){UserProfileService::respondToFriend((int)$user['user_id'],(int)$_POST['friendship_id'],true);$notice='Friend request accepted.';}
 if($action==='friend_decline'){UserProfileService::respondToFriend((int)$user['user_id'],(int)$_POST['friendship_id'],false);$notice='Friend request declined.';}
 if($action==='friend_remove'){UserProfileService::removeFriend((int)$user['user_id'],(int)$_POST['friendship_id']);$notice='Friend removed.';}
 if($action==='friend_label'){UserProfileService::saveFriendLabel((int)$user['user_id'],(int)$_POST['friendship_id'],(string)($_POST['label_text']??''));$notice='Friend group updated.';}
 if($action==='send_password_reset'){$result=AuthService::createPasswordResetForEmail((string)$user['email']);$notice=($result&&$result['sent'])?'Password-reset instructions sent to your email.':'Email delivery was unavailable. Use the reset link below.';$generatedUrl=$result['url']??null;}
 $user=AuthService::currentUser()??$user;
}catch(Throwable $e){$error=$e->getMessage();}}
$profile=UserProfileService::profile((int)$user['user_id']);$friends=UserProfileService::friends((int)$user['user_id']);$isWriter=(int)$user['is_admin']===1||AuthService::hasRole((int)$user['user_id'],'WRITER');$insights=$isWriter?UserProfileService::writerInsights((int)$user['user_id']):['stories'=>[],'reviews'=>[]];
function csrf_field():string{return'<input type="hidden" name="csrf_token" value="'.e(AuthService::csrfToken()).'">';}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My Profile · Toinky</title><style>
:root{font-family:Inter,system-ui,sans-serif;color:#1C242B;background:#F4EEE2}*{box-sizing:border-box}body{margin:0}.bar{background:#1C242B;color:#fff;padding:15px 22px}.barin,.shell{max-width:1160px;margin:auto}.barin{display:flex;align-items:center;justify-content:space-between;gap:16px}.nav{display:flex;align-items:center;gap:14px}.bar a{color:#F4EEE2;text-decoration:none}.shell{padding:32px 20px}.profile-head{display:grid;grid-template-columns:120px 1fr;gap:20px;align-items:center;margin-bottom:24px}.avatar{width:112px;height:112px;border-radius:50%;object-fit:cover;background:#d9d4ca;border:4px solid #fff;box-shadow:0 4px 18px #1c242b22}.avatar.placeholder{display:grid;place-items:center;color:#fff;background:#66715C;font:700 42px Georgia,serif}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.card{background:#fff;border:1px solid #d9d4ca;border-radius:14px;padding:20px}.wide{grid-column:1/-1}.field{display:block;margin:12px 0;font-weight:700}.field input,.field select{display:block;width:100%;margin-top:6px;padding:10px;border:1px solid #c9c3b9;border-radius:8px;font:inherit}.btn{border:0;border-radius:8px;background:#B58E46;color:#1C242B;padding:10px 14px;font:inherit;font-weight:800;cursor:pointer;text-decoration:none}.btn.alt{background:#fff;border:1px solid #6B2938;color:#6B2938}.btn.danger{background:#fff1f2;border:1px solid #fecdd3;color:#9f1239}.notice,.error{padding:12px;border-radius:9px;margin-bottom:16px}.notice{background:#dcfce7;color:#166534}.error{background:#fee2e2;color:#991b1b}.url{word-break:break-all;background:#f8fafc;padding:10px;border-radius:8px}.friend{display:grid;grid-template-columns:48px 1fr auto;gap:12px;align-items:center;padding:12px 0;border-top:1px solid #e5e1d8}.friend:first-of-type{border-top:0}.friend img,.friend-avatar{width:44px;height:44px;border-radius:50%;object-fit:cover;background:#66715C;color:#fff;display:grid;place-items:center;font-weight:800}.friend-actions{display:flex;gap:7px;flex-wrap:wrap;justify-content:flex-end}.friend-actions form{margin:0}.friend-label{display:flex;gap:6px;margin-top:7px}.friend-label input{min-width:0;padding:7px;border:1px solid #c9c3b9;border-radius:7px}.table{width:100%;border-collapse:collapse;font-size:13px}.table th,.table td{text-align:left;padding:9px 7px;border-bottom:1px solid #e5e1d8;vertical-align:top}.muted{color:#64748b}@media(max-width:760px){.grid{grid-template-columns:1fr}.wide{grid-column:auto}.barin{align-items:flex-start}.nav{flex-wrap:wrap;justify-content:flex-end}.profile-head{grid-template-columns:88px 1fr}.avatar{width:80px;height:80px}.friend{grid-template-columns:44px 1fr}.friend-actions{grid-column:2;justify-content:flex-start}}
</style><link rel="stylesheet" href="assets/toinky-theme.css"><link rel="stylesheet" href="assets/toinky-signed-header.css"><link rel="stylesheet" href="assets/toinky-profile.css"></head><body><?php require_once __DIR__.'/_signed_header.php';render_signed_header($user,'My Profile');?><main class="shell">
<?php if($error):?><div class="error"><?=e($error)?></div><?php endif;?><?php if($notice):?><div class="notice"><?=e($notice)?></div><?php endif;?><?php if($generatedUrl):?><div class="url"><?=e($generatedUrl)?></div><?php endif;?>
<section class="profile-head"><?php if($profile['profile_image_path']):?><img class="avatar" src="<?=e($profile['profile_image_path'])?>" alt="<?=e($profile['display_name'])?> profile photo"><?php else:?><span class="avatar placeholder" aria-hidden="true"><?=e(mb_strtoupper(mb_substr($profile['display_name'],0,1)))?></span><?php endif;?><div><h1>My Profile</h1><p class="muted"><?=e($profile['display_name'])?> · <?=e($profile['email'])?></p></div></section>
<nav class="profile-tabs" aria-label="Profile sections"><button class="active" type="button" data-profile-tab="account">Account</button><button type="button" data-profile-tab="friends">Friends</button><?php if($isWriter):?><button type="button" data-profile-tab="writer">Writer</button><?php endif;?></nav>
<div class="grid"><section class="card"><h2>Profile Photo</h2><form method="post" enctype="multipart/form-data"><?=csrf_field()?><input type="hidden" name="action" value="upload_profile_photo"><label class="field">JPG, PNG, or WebP · 5 MB maximum<input type="file" name="profile_photo" accept="image/jpeg,image/png,image/webp" required></label><button class="btn">Update Profile Photo</button></form></section>
<section class="card"><h2>Email And Password</h2><p class="muted">Email changes take effect only after you open the verification link sent to the new address.</p><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="request_email_change"><label class="field">New Email<input type="email" name="new_email" required></label><button class="btn">Verify New Email</button></form><form method="post" style="margin-top:18px"><?=csrf_field()?><input type="hidden" name="action" value="send_password_reset"><button class="btn alt">Send Password Reset</button></form></section>
<section class="card"><h2>Invite A Player</h2><p class="muted">Invite someone to create a Toinky account. Once they join, add them as a friend.</p><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="invite_player"><label class="field">Email<input type="email" name="email" required></label><button class="btn">Send Invitation</button></form></section>
<section class="card"><h2>Add A Friend</h2><p class="muted">Friend requests require the other player’s approval.</p><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="request_friend"><label class="field">Existing Player Email<input type="email" name="email" required></label><button class="btn">Send Friend Request</button></form></section>
<section class="card wide"><h2>Friends</h2><?php if(!$friends):?><p class="muted">No friends or pending requests yet.</p><?php endif;?><?php foreach($friends as$friend):$incoming=$friend['status']==='PENDING'&&(int)$friend['requested_by_user_id']!==(int)$user['user_id'];?><div class="friend"><?php if($friend['profile_image_path']):?><img src="<?=e($friend['profile_image_path'])?>" alt=""><?php else:?><span class="friend-avatar" aria-hidden="true"><?=e(mb_strtoupper(mb_substr($friend['display_name'],0,1)))?></span><?php endif;?><div><b><?=e($friend['display_name'])?></b><br><small class="muted"><?=e($friend['email'])?> · <?=e(ucfirst(strtolower($friend['status'])))?></small><?php if($friend['status']==='ACCEPTED'):?><form method="post" class="friend-label"><?=csrf_field()?><input type="hidden" name="action" value="friend_label"><input type="hidden" name="friendship_id" value="<?=(int)$friend['friendship_id']?>"><input name="label_text" maxlength="80" value="<?=e((string)$friend['label_text'])?>" placeholder="Group label, e.g. Family"><button class="btn alt">Save</button></form><?php endif;?></div><div class="friend-actions"><?php if($incoming):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="friend_accept"><input type="hidden" name="friendship_id" value="<?=(int)$friend['friendship_id']?>"><button class="btn">Accept</button></form><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="friend_decline"><input type="hidden" name="friendship_id" value="<?=(int)$friend['friendship_id']?>"><button class="btn alt">Decline</button></form><?php elseif($friend['status']==='ACCEPTED'):?><form method="post" onsubmit="return confirm('Remove this friend?')"><?=csrf_field()?><input type="hidden" name="action" value="friend_remove"><input type="hidden" name="friendship_id" value="<?=(int)$friend['friendship_id']?>"><button class="btn danger">Remove</button></form><?php endif;?></div></div><?php endforeach;?></section>
<?php if($isWriter):?><section class="card wide"><h2>My Story Performance</h2><?php if(!$insights['stories']):?><p class="muted">You do not have authored stories yet.</p><?php else:?><table class="table"><tr><th>Story</th><th>Status</th><th>Ratings</th><th>Average</th></tr><?php foreach($insights['stories']as$story):?><tr><td><?=e($story['title'])?></td><td><?=e($story['workflow_status'])?></td><td><?=(int)$story['rating_count']?></td><td><?=e($story['average_rating']??'—')?></td></tr><?php endforeach;?></table><?php endif;?></section><section class="card wide"><h2>My Story Reviews</h2><?php if(!$insights['reviews']):?><p class="muted">No submitted revisions have been reviewed yet.</p><?php else:?><table class="table"><tr><th>Story</th><th>Revision</th><th>Status</th><th>Review Notes</th><th>Reviewed</th></tr><?php foreach($insights['reviews']as$review):?><tr><td><?=e($review['title'])?></td><td><?=(int)$review['version_no']?></td><td><?=e($review['workflow_status'])?></td><td><?=e($review['review_notes']??'—')?></td><td><?=e($review['reviewed_at_utc']??'—')?></td></tr><?php endforeach;?></table><?php endif;?></section><?php endif;?></div><script src="assets/toinky-profile.js" defer></script></main></body></html>
